'use client'
import { Carousel } from '@/react/components/ui/Carousel'
// Recent work, three in view on wide screens and one on phones. Placeholders stand in for the pictures.
const work = [
  { title: 'Acme onboarding', meta: 'Product design, 6 weeks' },
  { title: 'Acme brand system', meta: 'Branding, 4 weeks' },
  { title: 'Acme dashboard', meta: 'Product design, 10 weeks' },
  { title: 'Acme website', meta: 'Development, 5 weeks' },
  { title: 'Acme mobile app', meta: 'Development, 12 weeks' },
]

export default function Work() {
  return (
    <div className="w-full max-w-238">
      <Carousel
        label="Recent work"
        count={work.length}
        perView={3}
        slide={({ index }) => (
          <div className="flex flex-col gap-3">
            <div className="flex aspect-[4/5] items-end rounded-container bg-surface-raised p-4">
              <span className="type-label text-fg-muted">{`Project ${index + 1}`}</span>
            </div>
            <div className="flex flex-col gap-1">
              <p className="type-ui-strong">{work[index]!.title}</p>
              <p className="type-caption text-fg-muted">{work[index]!.meta}</p>
            </div>
          </div>
        )}
      />
    </div>
  )
}

'use client'
import { Carousel } from '@/react/components/ui/Carousel'
// One quote at a time from Acme's team, on the raised fill.
const quotes = [
  'The first flow shipped in three weeks, and the system made the next one faster.',
  'Our engineers build from the components now. Reviews are shorter.',
  'It felt like one team, not a vendor.',
]

export default function Quotes() {
  return (
    <div className="w-full max-w-150">
      <Carousel
        label="Quotes"
        count={quotes.length}
        slide={({ index }) => (
          <figure className="flex h-full flex-col justify-between gap-8 rounded-container bg-surface-raised p-8 max-sm:p-6">
            <blockquote className="type-heading-3">{quotes[index]}</blockquote>
            <figcaption className="type-caption text-fg-muted">Acme product team</figcaption>
          </figure>
        )}
      />
    </div>
  )
}

